package com.nexodb.db;

import com.nexodb.model.DatabaseType;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.sql.*;
import java.time.Instant;
import java.util.*;
import java.util.function.Consumer;

/** Streamed logical backup/restore for relational engines other than MySQL/MariaDB. */
public final class PortableBackupService {
    public record Report(int objects,long rows,Path file) {}
    private record Column(String name,int jdbcType,String typeName,int size,int scale,boolean nullable,String defaultValue,boolean autoIncrement) {}
    private PortableBackupService() {}

    public static boolean supported(DatabaseType type){return type==DatabaseType.POSTGRESQL||type==DatabaseType.SQLSERVER||type==DatabaseType.ORACLE||type==DatabaseType.SQLITE||type==DatabaseType.H2;}

    public static List<SqlBackupService.ObjectInfo> objects(Connection connection,String database)throws SQLException{
        List<SqlBackupService.ObjectInfo> result=new ArrayList<>();DatabaseMetaData meta=connection.getMetaData();String catalog=catalog(connection,database),schema=schema(connection,database);
        readObjects(meta,catalog,schema,result);if(result.isEmpty()&&(catalog!=null||schema!=null))readObjects(meta,null,null,result);
        result.sort(Comparator.comparing(SqlBackupService.ObjectInfo::name,String.CASE_INSENSITIVE_ORDER));return List.copyOf(result);
    }
    private static void readObjects(DatabaseMetaData meta,String catalog,String schema,List<SqlBackupService.ObjectInfo> result)throws SQLException{
        try(ResultSet rows=meta.getTables(catalog,schema,"%",new String[]{"TABLE","VIEW"})){while(rows.next()){String name=rows.getString("TABLE_NAME"),kind=rows.getString("TABLE_TYPE");if(name==null||name.equalsIgnoreCase(MigrationService.HISTORY_TABLE))continue;result.add(new SqlBackupService.ObjectInfo("VIEW".equalsIgnoreCase(kind)?SqlBackupService.Kind.VIEW:SqlBackupService.Kind.TABLE,name,"",""));}}
    }

    public static Report write(Connection connection,DatabaseType type,String database,List<SqlBackupService.ObjectInfo> objects,SqlBackupService.Options options,Path file,SqlTransferControl control,Consumer<SqlBackupService.Progress> progress)throws Exception{
        if(!supported(type))throw new IllegalArgumentException("Este motor no admite el respaldo SQL portátil.");
        List<SqlBackupService.ObjectInfo> selected=objects.stream().filter(o->o.kind()==SqlBackupService.Kind.TABLE||o.kind()==SqlBackupService.Kind.VIEW).toList();if(options.mode()==SqlBackupService.Mode.DATA)selected=selected.stream().filter(o->o.kind()==SqlBackupService.Kind.TABLE).toList();if(selected.isEmpty())throw new IllegalArgumentException("Selecciona al menos una tabla o vista.");
        Path target=file.toAbsolutePath();Path parent=target.getParent();if(parent==null)throw new IOException("La ruta de respaldo no tiene una carpeta válida.");Files.createDirectories(parent);Path temp=Files.createTempFile(parent,"adisdb-portable-backup-",".part");boolean snapshot=false;long rows=0;int completed=0;boolean originalAuto=connection.getAutoCommit();
        try{
            if(options.consistent()&&options.mode()!=SqlBackupService.Mode.STRUCTURE){connection.setAutoCommit(false);snapshot=true;}
            try(Writer out=Files.newBufferedWriter(temp,StandardCharsets.UTF_8)){
                out.write("-- AdisDB portable SQL backup · "+Instant.now()+"\n-- Engine: "+type+"\n-- Database: "+database.replace('\n',' ').replace('\r',' ')+"\n\n");
                if(options.disableForeignKeys())writeForeignKeys(out,type,false);
                if(options.mode()!=SqlBackupService.Mode.DATA){List<SqlBackupService.ObjectInfo> reverse=new ArrayList<>(selected);Collections.reverse(reverse);if(options.drop())for(var object:reverse)out.write("DROP "+(object.kind()==SqlBackupService.Kind.VIEW?"VIEW":"TABLE")+" IF EXISTS "+qualified(connection,type,database,object.name())+";\n");for(var object:selected){control.check();if(object.kind()==SqlBackupService.Kind.TABLE)out.write(createTable(connection,type,database,object.name())+";\n\n");else{String ddl=viewDefinition(connection,type,database,object.name());out.write(ddl.isBlank()?"-- Vista no exportada automáticamente: "+object.name()+"\n":ddl+";\n\n");}if(options.mode()==SqlBackupService.Mode.STRUCTURE)progress.accept(new SqlBackupService.Progress(object.name(),rows,++completed,selected.size()));}}
                if(options.mode()!=SqlBackupService.Mode.STRUCTURE)for(var object:selected)if(object.kind()==SqlBackupService.Kind.TABLE){control.check();rows+=writeData(connection,type,database,object.name(),out,control);progress.accept(new SqlBackupService.Progress(object.name(),rows,++completed,selected.size()));}
                if(options.disableForeignKeys())writeForeignKeys(out,type,true);out.write("\n-- Backup complete\n");
            }
            if(snapshot){connection.rollback();snapshot=false;}try{Files.move(temp,target,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException ignored){Files.move(temp,target,StandardCopyOption.REPLACE_EXISTING);}return new Report(selected.size(),rows,target);
        }finally{try{if(snapshot)connection.rollback();if(connection.getAutoCommit()!=originalAuto)connection.setAutoCommit(originalAuto);}finally{Files.deleteIfExists(temp);}}
    }

    public static SqlImportService.Report restore(Connection connection,DatabaseType type,SqlImportService.Analysis analysis,SqlTransferControl control,Consumer<SqlImportService.Progress> progress)throws Exception{
        if(!supported(type))throw new IllegalArgumentException("Este motor no admite la restauración SQL portátil.");boolean transactional=type==DatabaseType.POSTGRESQL||type==DatabaseType.SQLSERVER||type==DatabaseType.SQLITE||type==DatabaseType.H2;boolean original=connection.getAutoCommit();long completed=0;int line=1;
        try{if(transactional)connection.setAutoCommit(false);try(Reader input=Files.newBufferedReader(analysis.file(),StandardCharsets.UTF_8);SqlScriptReader reader=new SqlScriptReader(input)){SqlScriptReader.Statement item;while((item=reader.next())!=null){control.check();line=item.line();try(Statement statement=connection.createStatement()){control.active(statement);statement.execute(item.sql());}finally{control.active(null);}completed++;progress.accept(new SqlImportService.Progress(completed,analysis.statements(),line));}}if(transactional)connection.commit();return new SqlImportService.Report(completed,0);
        }catch(Exception error){if(transactional)try{connection.rollback();}catch(SQLException rollback){error.addSuppressed(rollback);}if(error instanceof java.util.concurrent.CancellationException)throw error;throw new SqlImportService.ImportFailure(completed,line,error);}finally{if(connection.getAutoCommit()!=original)connection.setAutoCommit(original);}
    }

    private static String createTable(Connection connection,DatabaseType type,String database,String table)throws SQLException{
        DatabaseMetaData meta=connection.getMetaData();String catalog=catalog(connection,database),schema=schema(connection,database);List<Column> columns=new ArrayList<>();try(ResultSet rows=meta.getColumns(catalog,schema,table,"%")){while(rows.next())columns.add(new Column(rows.getString("COLUMN_NAME"),rows.getInt("DATA_TYPE"),rows.getString("TYPE_NAME"),rows.getInt("COLUMN_SIZE"),rows.getInt("DECIMAL_DIGITS"),rows.getInt("NULLABLE")!=DatabaseMetaData.columnNoNulls,rows.getString("COLUMN_DEF"),"YES".equalsIgnoreCase(safe(rows,"IS_AUTOINCREMENT")))) ;}
        if(columns.isEmpty())throw new SQLException("No se pudieron leer las columnas de "+table);List<String> pk=new ArrayList<>();try(ResultSet keys=meta.getPrimaryKeys(catalog,schema,table)){TreeMap<Short,String> ordered=new TreeMap<>();while(keys.next())ordered.put(keys.getShort("KEY_SEQ"),keys.getString("COLUMN_NAME"));pk.addAll(ordered.values());}
        List<String> definitions=new ArrayList<>();for(Column column:columns){StringBuilder value=new StringBuilder(quote(type,column.name())).append(' ').append(renderType(type,column));if(column.autoIncrement())value.append(identity(type));if(column.defaultValue()!=null&&!column.defaultValue().isBlank()&&!column.autoIncrement())value.append(" DEFAULT ").append(column.defaultValue());if(!column.nullable())value.append(" NOT NULL");definitions.add(value.toString());}if(!pk.isEmpty())definitions.add("PRIMARY KEY ("+String.join(",",pk.stream().map(name->quote(type,name)).toList())+")");return "CREATE TABLE "+qualified(connection,type,database,table)+" (\n  "+String.join(",\n  ",definitions)+"\n)";
    }
    private static String renderType(DatabaseType type,Column column){String name=column.typeName()==null?"VARCHAR":column.typeName();String upper=name.toUpperCase(Locale.ROOT);if(upper.contains("CHAR")||upper.contains("BINARY"))return name+(column.size()>0?"("+column.size()+")":"");if(Set.of(Types.NUMERIC,Types.DECIMAL).contains(column.jdbcType())&&column.size()>0)return name+"("+column.size()+","+Math.max(0,column.scale())+")";return name;}
    private static String identity(DatabaseType type){return switch(type){case POSTGRESQL,H2->" GENERATED BY DEFAULT AS IDENTITY";case SQLSERVER->" IDENTITY(1,1)";case ORACLE->" GENERATED BY DEFAULT AS IDENTITY";default->"";};}
    private static long writeData(Connection connection,DatabaseType type,String database,String table,Writer out,SqlTransferControl control)throws Exception{String target=qualified(connection,type,database,table);long rows=0;try(Statement statement=connection.createStatement(ResultSet.TYPE_FORWARD_ONLY,ResultSet.CONCUR_READ_ONLY)){statement.setFetchSize(256);control.active(statement);try(ResultSet result=statement.executeQuery("SELECT * FROM "+target)){ResultSetMetaData meta=result.getMetaData();while(result.next()){control.check();out.write("INSERT INTO "+target+" VALUES (");for(int i=1;i<=meta.getColumnCount();i++){if(i>1)out.write(',');writeValue(result,i,meta.getColumnType(i),type,out);}out.write(");\n");rows++;}}finally{control.active(null);}}return rows;}
    private static void writeValue(ResultSet result,int index,int jdbcType,DatabaseType type,Writer out)throws Exception{if(Set.of(Types.BINARY,Types.VARBINARY,Types.LONGVARBINARY,Types.BLOB).contains(jdbcType)){byte[] value=result.getBytes(index);if(value==null)out.write("NULL");else{String hex=HexFormat.of().formatHex(value);out.write(switch(type){case POSTGRESQL->"decode('"+hex+"','hex')";case SQLSERVER->"0x"+hex;case ORACLE->"hextoraw('"+hex+"')";default->"X'"+hex+"'";});}return;}String value=result.getString(index);if(value==null){out.write("NULL");return;}if(Set.of(Types.TINYINT,Types.SMALLINT,Types.INTEGER,Types.BIGINT,Types.NUMERIC,Types.DECIMAL,Types.REAL,Types.FLOAT,Types.DOUBLE).contains(jdbcType)&&value.matches("[+-]?(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)(?:[eE][+-]?[0-9]+)?")){out.write(value);return;}if(jdbcType==Types.BOOLEAN||jdbcType==Types.BIT){out.write(type==DatabaseType.POSTGRESQL?(result.getBoolean(index)?"TRUE":"FALSE"):(result.getBoolean(index)?"1":"0"));return;}out.write("'"+value.replace("'","''")+"'");}
    private static String viewDefinition(Connection connection,DatabaseType type,String database,String view)throws SQLException{String sql=switch(type){case POSTGRESQL->"SELECT definition FROM pg_views WHERE schemaname=current_schema() AND viewname=?";case SQLSERVER->"SELECT OBJECT_DEFINITION(OBJECT_ID(?))";case ORACLE->"SELECT text FROM user_views WHERE view_name=?";case SQLITE->"SELECT sql FROM sqlite_master WHERE type='view' AND name=?";case H2->"SELECT VIEW_DEFINITION FROM INFORMATION_SCHEMA.VIEWS WHERE TABLE_NAME=?";default->"";};if(sql.isBlank())return "";try(PreparedStatement statement=connection.prepareStatement(sql)){statement.setString(1,type==DatabaseType.ORACLE||type==DatabaseType.H2?view.toUpperCase(Locale.ROOT):view);try(ResultSet result=statement.executeQuery()){if(!result.next())return "";String definition=result.getString(1);if(definition==null)return "";return definition.trim().toUpperCase(Locale.ROOT).startsWith("CREATE")?definition:"CREATE VIEW "+qualified(connection,type,database,view)+" AS "+definition;}}catch(SQLException error){return "";}}
    private static void writeForeignKeys(Writer out,DatabaseType type,boolean enable)throws IOException{String sql=switch(type){case POSTGRESQL->"SET session_replication_role = "+(enable?"origin":"replica")+";";case SQLSERVER->"-- Usa ALTER TABLE ... "+(enable?"WITH CHECK CHECK":"NOCHECK")+" CONSTRAINT ALL por tabla si es necesario";case SQLITE->"PRAGMA foreign_keys = "+(enable?"ON":"OFF")+";";case H2->"SET REFERENTIAL_INTEGRITY "+(enable?"TRUE":"FALSE")+";";default->"-- Las claves foráneas permanecen activas en este motor";};out.write(sql+"\n");}
    private static String qualified(Connection connection,DatabaseType type,String database,String object)throws SQLException{if(type==DatabaseType.SQLITE||type==DatabaseType.H2||type==DatabaseType.ORACLE)return quote(type,object);String schema=connection.getSchema();if(type==DatabaseType.POSTGRESQL&&schema!=null&&!schema.isBlank())return quote(type,schema)+"."+quote(type,object);if(type==DatabaseType.SQLSERVER&&database!=null&&!database.isBlank())return quote(type,database)+"."+quote(type,schema==null||schema.isBlank()?"dbo":schema)+"."+quote(type,object);return quote(type,object);}
    private static String quote(DatabaseType type,String name){return type==DatabaseType.SQLSERVER?"["+name.replace("]","]]")+"]":"\""+name.replace("\"","\"\"")+"\"";}
    private static String catalog(Connection connection,String database)throws SQLException{String product=connection.getMetaData().getDatabaseProductName().toLowerCase(Locale.ROOT);if(product.contains("postgres")||product.contains("sqlite"))return null;if(product.contains("h2"))return connection.getCatalog();return database==null||database.isBlank()?connection.getCatalog():database;}
    private static String schema(Connection connection,String database)throws SQLException{String product=connection.getMetaData().getDatabaseProductName().toLowerCase(Locale.ROOT);return product.contains("postgres")||product.contains("h2")?connection.getSchema():null;}
    private static String safe(ResultSet row,String column){try{return row.getString(column);}catch(SQLException ignored){return "";}}
}
